// @whimtex-effect Samples/Spiral Filaments
// @control(_Opacity)
// @param hidden float _Opacity = 0.55 [0 .. 1]
// @param float _Turns = 2.4 [0.1 .. 5]
// @param float _Count = 11 [2 .. 32]
// @param color _Tint = (0.5803922, 0.458823532, 1, 1)

float4 ApplyFX(float2 uv,float4 color){
 float2 p=uv-.5;float r=length(p);float a=atan2(p.y,p.x+1e-7);
 float phase=a*_Count+r*_Turns*70+sin(a*3+r*25)*1.7;
 float thread=pow(saturate(cos(phase)),42);
 float fade=smoothstep(.12,.23,r)*(1-smoothstep(.32,.46,r));
 float gaps=smoothstep(-.2,.4,sin(a*7+r*35));
 return float4(_Tint.rgb,thread*fade*gaps*_Opacity);}

// @whimtex-effect Samples/Energy Motes
// @control(_Amount)
// @param hidden float _Amount = 0.65 [0 .. 1]
// @param float _Seed = 53 [0 .. ~1000]
// @param color _Tint = (0.647058845, 0.8666667, 1, 1)

float HashM(float2 p){return frac(sin(dot(p,float2(127.1,311.7))+_Seed)*43758.5453);}
float4 ApplyFX(float2 uv,float4 color){
 float2 q=uv*38;float2 id=floor(q);float2 local=frac(q);
 float h=HashM(id);float2 center=float2(HashM(id+2.7),HashM(id+15.4))*.7+.15;
 float d=length((local-center)*float2(1,1.7));float size=lerp(.025,.11,HashM(id+87));
 float spark=(1-smoothstep(size*.35,size,d))+exp(-d*18)*.18;
 float r=length(uv-.5);float region=smoothstep(.16,.22,r)*(1-smoothstep(.40,.48,r));
 return float4(_Tint.rgb,saturate(spark*step(.68,h)*region*_Amount));}

// @whimtex-effect Samples/Fractured Orbitals
// @control(_Opacity)
// @param hidden float _Opacity = 0.85 [0 .. 1]
// @group(Orbitals)
// @param float _Radius = 0.29 [0.1 .. 0.45]
// @param float _Seed = 7 [0 .. ~100]
// @param color _Tint = (0.490196079, 0.9764706, 1, 1)
// @endgroup

float4 ApplyFX(float2 uv,float4 color){
 float2 p=uv-.5;float r=length(p);float a=atan2(p.y,p.x+1e-7);float coverage=0;
 for(int i=0;i<4;i++){float rad=_Radius+i*.032;float phase=a*(11+i*3)+i*2.1;
 float broken=smoothstep(-.25,.05,sin(phase)+.2*sin(a*31));
 float band=exp(-abs(r-rad)*1800)*broken;
 float ticks=pow(saturate(cos(a*(64+i*11))),30)*exp(-abs(r-rad-.006)*400);
 coverage+=band+ticks*.5;}
 float wavy=_Radius-.023+sin(a*17+_Seed)*.004+sin(a*49)*.002;
 coverage+=exp(-abs(r-wavy)*1100)*smoothstep(-.2,.2,sin(a*5));
 return float4(_Tint.rgb,saturate(coverage)*_Opacity);}

// @whimtex-effect Samples/Twirl
// @group(Twirl Angle; _Angle)
// @param hidden float _Angle = 145 [~-720 .. ~720]
// @if _Angle != 0
// @param transform2D _Area = (0.5, 0.5, 1, 1, 0)
// @endif
// @endgroup


float4 ApplyFX(float2 uv, float4 color)
{
    if (_Angle == 0) return color;

    float2 p = (_Area_ToLocal(uv) - 0.5) * 2.0;
    // Angle is the visible rotation at local radius 1; it continues beyond it.
    float angle = -radians(_Angle) * length(p);
    float sine, cosine;
    sincos(angle, sine, cosine);
    float2 rotated = float2(cosine * p.x - sine * p.y, sine * p.x + cosine * p.y);
    return SampleInput(_Area_ToInput(0.5 + rotated * 0.5));
}

// @whimtex-effect Samples/Plasma Envelope
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @group(Ring)
// @param float _Radius = 0.34 [0.1 .. 0.45]
// @param float _Width = 0.035 [0.01 .. 0.15]
// @param float _Roughness = 0.035 [0 .. 0.1]
// @endgroup
// @param gradient _Tint = (0, 0, 0, 1) -> (1, 1, 1, 1)

float4 ApplyFX(float2 uv,float4 color) {
 float n=saturate(color.r); float d=length(uv-0.5);
 float ridge=abs(d-_Radius+(n-0.5)*_Roughness);
 float body=exp(-pow(ridge/_Width,2.0)*3.0);
 float filament=pow(saturate(n),2.2);
 float a=saturate(body*(0.12+1.7*filament))*_Opacity;
 a*=1-smoothstep(.43,.48,d); a*=smoothstep(.20,.24,d);
 float t=saturate(0.2+filament*1.5+exp(-ridge*220.0)*0.3);
 return float4(_Tint_Sample(t).rgb,a);
}
